INSERT INTO spectacle (id, titre, description, url_video, horaire_previsionnel, id_soiree, id_style) VALUES
  (1, 'Velvet Thunder', 'Après 3 albums et des centaines de concerts, Velvet Thunder propose un métal aux riffs massifs. Attendez-vous à un show explosif.', 'https://www.youtube.com/watch?v=fwQVJRl-h26', '21:00', 1, 2),
  (2, 'Wild Saturn', 'Tout droit venu de Berlin, Wild Saturn propose un métal aux riffs massifs. Premier passage au festival, et sûrement pas le dernier.', 'https://www.youtube.com/watch?v=DIgWaBLGqbV', '22:15', 1, 2),
  (3, 'Black Mirage', 'Révélation de la scène métal de ces dernières années, Black Mirage propose un métal lourd et sans concession. Sur scène, le groupe ne laisse personne immobile.', 'https://www.youtube.com/watch?v=9-IGcrS_3f9', '23:30', 1, 2),
  (4, 'Les Mirabelles Hurlantes', 'Tout droit venu de Manchester, Les Mirabelles Hurlantes propose un pop rock aux mélodies accrocheuses. Sur scène, le groupe ne laisse personne immobile.', 'https://www.youtube.com/watch?v=nQY3JEuJnqs', '21:00', 2, 6),
  (5, 'Les Vagabonds du Plateau', 'Révélation de la scène pop rock de ces dernières années, Les Vagabonds du Plateau propose un pop rock lumineux et entraînant. Premier passage au festival, et sûrement pas le dernier.', 'https://www.youtube.com/watch?v=DLcJjeDrTlw', '22:15', 2, 6),
  (6, 'Thunder Moth', 'Tout droit venu de Seattle, Thunder Moth propose un punk rapide et rageur. Attendez-vous à un show explosif.', 'https://www.youtube.com/watch?v=Z9IXUjE9gH3', '21:00', 3, 5),
  (7, 'Les Corbeaux de Lorraine', 'Après 2 albums et des centaines de concerts, Les Corbeaux de Lorraine propose un blues rock aux guitares slide brûlantes. Premier passage au festival, et sûrement pas le dernier.', 'https://www.youtube.com/watch?v=Fhu84c2OFzW', '22:15', 3, 1),
  (8, 'Steel Orchid', 'Formé à Berlin en 2013, Steel Orchid propose un blues rock chaud comme un bar du Mississippi. Attendez-vous à un show explosif.', 'https://www.youtube.com/watch?v=51KIxgRBNz0', '19:30', 4, 1),
  (9, 'Brick Lane Riot', 'Formé à Lyon en 2022, Brick Lane Riot propose un blues rock aux guitares slide brûlantes. Leur nouvel album sort au printemps 2027 : la tournée passe par Nancy.', 'https://www.youtube.com/watch?v=aArBnIfj526', '20:45', 4, 1),
  (10, 'Red Canyon', 'Tout droit venu de Manchester, Red Canyon propose un blues rock aux guitares slide brûlantes. Premier passage au festival, et sûrement pas le dernier.', 'https://www.youtube.com/watch?v=FcROLvHg0gN', '22:00', 4, 1),
  (11, 'Neon Cathedral', 'Après 2 albums et des centaines de concerts, Neon Cathedral propose un rock psyché hypnotique. Attendez-vous à un show explosif.', 'https://www.youtube.com/watch?v=Or9UDKpuHpt', '19:30', 5, 7),
  (12, 'Ultra Violette', 'Révélation de la scène rock psyché de ces dernières années, Ultra Violette propose un rock psyché nourri de synthés vintage. Premier passage au festival, et sûrement pas le dernier.', 'https://www.youtube.com/watch?v=HSWFBbG9jLm', '20:45', 5, 7),
  (13, 'Mudslide Brothers', 'Révélation de la scène hard rock de ces dernières années, Mudslide Brothers propose un hard rock aux solos interminables. Sur scène, le groupe ne laisse personne immobile.', 'https://www.youtube.com/watch?v=r2Megkn2kCb', '20:00', 6, 4),
  (14, 'Ash & Ivory', 'Tout droit venu de Austin, Ash & Ivory propose un hard rock hérité des grandes heures des années 80. Un live à ne pas manquer.', 'https://www.youtube.com/watch?v=Qj2xKeEib3Q', '21:15', 6, 4),
  (15, 'Lune Noire', 'Révélation de la scène blues rock de ces dernières années, Lune Noire propose un blues rock chaud comme un bar du Mississippi. Un live à ne pas manquer.', 'https://www.youtube.com/watch?v=jzZN-dHCyNj', '21:00', 7, 1),
  (16, 'Bad Weather Club', 'Révélation de la scène blues rock de ces dernières années, Bad Weather Club propose un blues rock aux guitares slide brûlantes. Premier passage au festival, et sûrement pas le dernier.', 'https://www.youtube.com/watch?v=cBZm5LlLFp7', '22:15', 7, 1),
  (17, 'Pale Horizon', 'Révélation de la scène blues rock de ces dernières années, Pale Horizon propose un blues rock poisseux et habité. Un live à ne pas manquer.', 'https://www.youtube.com/watch?v=TAKfX-L7sCX', '23:30', 7, 1),
  (18, 'Static Monks', 'Après 2 albums et des centaines de concerts, Static Monks propose un hard rock hérité des grandes heures des années 80. Attendez-vous à un show explosif.', 'https://www.youtube.com/watch?v=CpG__4kzSuy', '20:00', 8, 4),
  (19, 'Sonic Bisons', 'Tout droit venu de Strasbourg, Sonic Bisons propose un pop rock aux mélodies accrocheuses. Leur nouvel album sort au printemps 2027 : la tournée passe par Nancy.', 'https://www.youtube.com/watch?v=hkmWLBn1jD9', '21:15', 8, 6),
  (20, 'Kinky Lanterns', 'Révélation de la scène grunge de ces dernières années, Kinky Lanterns propose un grunge sale et mélancolique. Sur scène, le groupe ne laisse personne immobile.', 'https://www.youtube.com/watch?v=Ja4fh-lB9av', '21:00', 9, 8),
  (21, 'Molotov Garden', 'Révélation de la scène grunge de ces dernières années, Molotov Garden propose un grunge aux guitares saturées. Leur nouvel album sort au printemps 2027 : la tournée passe par Nancy.', 'https://www.youtube.com/watch?v=nyxWmNU7pNb', '22:15', 9, 8),
  (22, 'Ghost Highway', 'Après 2 albums et des centaines de concerts, Ghost Highway propose un hard rock aux solos interminables. Leur nouvel album sort au printemps 2027 : la tournée passe par Nancy.', 'https://www.youtube.com/watch?v=_ZcoJirL5sj', '20:00', 10, 4),
  (23, 'Cobalt Riders', 'Après 4 albums et des centaines de concerts, Cobalt Riders propose un hard rock hérité des grandes heures des années 80. Sur scène, le groupe ne laisse personne immobile.', 'https://www.youtube.com/watch?v=N09UUFDpk1e', '21:15', 10, 4),
  (24, 'Electric Moose', 'Formé à Austin en 2017, Electric Moose propose un hard rock hérité des grandes heures des années 80. Premier passage au festival, et sûrement pas le dernier.', 'https://www.youtube.com/watch?v=BEEfcrx0Hhc', '22:30', 10, 4),
  (25, 'Gravity Sons', 'Révélation de la scène blues rock de ces dernières années, Gravity Sons propose un blues rock aux guitares slide brûlantes. Un live à ne pas manquer.', 'https://www.youtube.com/watch?v=ugl7S61t9Cn', '20:30', 11, 1),
  (26, 'Dust Prophets', 'Révélation de la scène rock de ces dernières années, Dust Prophets propose un rock direct et efficace. Un live à ne pas manquer.', 'https://www.youtube.com/watch?v=faCyOtBUngI', '21:45', 11, 3),
  (27, 'Feedback Sisters', 'Tout droit venu de Bruxelles, Feedback Sisters propose un hard rock hérité des grandes heures des années 80. Leur nouvel album sort au printemps 2027 : la tournée passe par Nancy.', 'https://www.youtube.com/watch?v=pbTdZFs6Bpj', '19:30', 12, 4),
  (28, 'Deep Blue Lizard', 'Révélation de la scène hard rock de ces dernières années, Deep Blue Lizard propose un hard rock aux solos interminables. Sur scène, le groupe ne laisse personne immobile.', 'https://www.youtube.com/watch?v=tEA2CMMLmO6', '20:45', 12, 4),
  (29, 'Copper Saints', 'Formé à Lille en 2017, Copper Saints propose un rock nerveux et généreux. Leur nouvel album sort au printemps 2027 : la tournée passe par Nancy.', 'https://www.youtube.com/watch?v=jHfJJv6lbYo', '20:00', 13, 3),
  (30, 'Polaroid Youth', 'Révélation de la scène rock de ces dernières années, Polaroid Youth propose un rock nerveux et généreux. Un live à ne pas manquer.', 'https://www.youtube.com/watch?v=das5Y4URtHE', '21:15', 13, 3),
  (31, 'Magma Club', 'Formé à Strasbourg en 2021, Magma Club propose un rock aux refrains imparables. Un live à ne pas manquer.', 'https://www.youtube.com/watch?v=M2fAqy8NseW', '22:30', 13, 3),
  (32, 'Satellite Dogs', 'Révélation de la scène métal de ces dernières années, Satellite Dogs propose un métal aux riffs massifs. Leur nouvel album sort au printemps 2027 : la tournée passe par Nancy.', 'https://www.youtube.com/watch?v=fXfvI4njFZK', '21:00', 14, 2),
  (33, 'Les Fils du Granit', 'Formé à Austin en 2020, Les Fils du Granit propose un métal aux riffs massifs. Leur nouvel album sort au printemps 2027 : la tournée passe par Nancy.', 'https://www.youtube.com/watch?v=aw9fO1aIc0j', '22:15', 14, 2),
  (34, 'Les Ombres Électriques', 'Tout droit venu de Bordeaux, Les Ombres Électriques propose un rock direct et efficace. Un live à ne pas manquer.', 'https://www.youtube.com/watch?v=SVLD2D6yfIu', '23:00', 15, 3),
  (35, 'Burning Vinyl', 'Formé à Liège en 2013, Burning Vinyl propose un rock aux refrains imparables. Premier passage au festival, et sûrement pas le dernier.', 'https://www.youtube.com/watch?v=kyPkQD4IQcA', '00:15', 15, 3);
